import { UPDATE_USERS } from "../actions/types";
const initialState = {
  page: {}
};

export default function(state = initialState, action) {
  switch (action.type) {
    case UPDATE_USERS:
      console.log(action.payload);
      return {
        ...state,
        page: action.payload
      };
    default: {
      return state;
    }
  }
}
